  // ═══════════════════════════════════════════════════════════════════════════════════════════════
  //  CHECK WORK — squiggy reads the WHOLE file (or every file) and hands back a walkable list.
  //  Sum 2026-07-29. A BUTTON, NEVER AUTOMATIC. Nothing sweeps behind your back.
  //
  //  THE RATCHET — four rungs. A rung only opens when the one below is EMPTY.
  //    1 VERIFIED  free. no model. facts: does it PARSE → can a DISABLED PERSON USE IT (ADA)
  //                → over the IC ceiling → declared twice → the mechanical IC rules.
  //    2 CLAIMED   the model's bug findings, each with a LINE NUMBER you can check in 5 seconds.
  //    3 TASTE     style, cited BY IC RULE NUMBER (24-ic-rules.js). Never freestyle.
  //    4 CROWD     what humans gripe about / love / keep asking for (26-sweep-better.js).
  //                Only when 1–3 are empty — you do not go shopping while the house is on fire.
  //
  //  THERE IS NO WISH RUNG. There was, and Sum cut it (2026-07-29): "what I wanted from 5 was 4."
  //  A model inventing a feature nobody asked for is the SAME SLOT as asking the crowd what they
  //  actually want — and only one of those two answers has a human behind it. So the model's
  //  daydream lost the slot to the crowd's evidence, and WISHLIST.md is now fed by cited human
  //  wants instead of machine daydreams.
  //
  //  You can still ask a bot to dream of electric sheep. You just have to ASK — squiggy's chat is
  //  right there and already answers questions. The sweep will never volunteer it, because an
  //  un-asked-for idea offered automatically is how a review turns into idea confetti.
  //
  //  WHY IT IS A RATCHET AND NOT A TREADMILL: each rung is gated by the one under it, so you
  //  cannot drift into feature-shopping while bugs exist. Sweep, fix, sweep again. It only turns
  //  one way. Keep turning it and you arrive at an ADA gold-standard app humans actually want.
  //
  //  SCOPE comes from the ▾ dropdown Sum already built (tab · all open tabs · the whole app).
  //  It was standing there working the whole time; the sweep just never read it.
  //
  //  THE LIST GROWS AS IT GOES. Rung 1 is free, so it runs over EVERY file first and you have a
  //  list in milliseconds. Then the model pass walks file by file, appending, saving after each —
  //  if the session dies at file 30 of 47, the first 30 are already on disk.
  //
  //  200 OF THE SAME MISTAKE IS ONE FINDING, NOT 200. You never walk 200 steps. The finding
  //  carries every hit line, and FIX ALL patches them in one press.
  // ═══════════════════════════════════════════════════════════════════════════════════════════════
  let _sweep = null      // { items:[{kind,line,why,file,hits}], at, path, scope }
  let _sweepRun = false  // a model pass is in flight — the 🔍 button becomes STOP
  let _sweepClean = null // the last sweep that came back EMPTY. this is the key to rung 5. null = 🌍 stays dark.

  const SWEEP_RUNGS = { VERIFIED: '🔒', CLAIMED: '🔎', TASTE: '🎨', CROWD: '🌍' }

  // ── what to read. the active tab is LIVE in the editor; the others are their saved content ────
  function sweepSrcOf(t) { return (active() && active().id === t.id && editor) ? editor.getValue() : (t.content || '') }

  function sweepTargets() {
    if (_sqScope === 'tabs') return tabs.filter(t => /\.(js|css|html|json|md|py|rs|txt|sh)$/i.test(t.filename || '')).map(t => ({ name: t.filename, src: sweepSrcOf(t) }))
    if (_sqScope === 'sandbox') {
      const sb = window.SANDBOX || {}
      return Object.keys(sb).filter(n => isTextFile(sb[n])).sort().map(n => {
        const open = tabs.find(t => t.filename === n)
        return { name: n, src: open ? sweepSrcOf(open) : (sb[n].data || '') }   // an open tab's unsaved edits beat the cache
      })
    }
    const t = active()
    return [{ name: (t && t.filename) || 'code', src: editor ? editor.getValue() : (t && t.content) || '' }]
  }

  // ── rung 1: free, deterministic. no model, no network, no chance of being talked into it ──────
  function sweepVerified(src, fn) {
    const out = [], lines = src.split('\n')
    try { new Function(src) } catch (e) {
      if (e instanceof SyntaxError) out.push({ kind: 'VERIFIED', line: 0, why: 'does not parse — ' + e.message })
    }
    // ADA first, right after "does it parse" — Sum's order. An unnamed control is a DEFECT, not a
    // taste call: a11y is how he actually operates this app. The checks live in IC_RULES so each cites its number.
    IC_RULES.forEach(r => { if (r.ada) { const f = icScan(r, lines); if (f) out.push(f) } })
    if (lines.length > 1080) out.push({ kind: 'VERIFIED', line: lines.length, rule: '1', why: `${lines.length} lines — over the IC ceiling (1080). it wants splitting.` })
    const seen = {}
    lines.forEach((l, i) => {
      const m = /^\s*(?:function|const|let|var)\s+([A-Za-z_$][\w$]*)/.exec(l)
      if (!m) return
      if (seen[m[1]]) out.push({ kind: 'VERIFIED', line: i + 1, why: `${m[1]} declared twice (also L${seen[m[1]]}) — the later one wins silently` })
      else seen[m[1]] = i + 1
    })
    IC_RULES.forEach(r => { if (!r.ada && (r.re || r.test)) { const f = icScan(r, lines); if (f) out.push(f) } })
    out.forEach(x => { x.file = fn })
    return out
  }

  // ── the ask. ONE call per file. line-based so a small local model hits the format reliably ────
  function sweepPrompt(src, fn) {
    return `Review this whole file, ${fn}. Report findings ONE PER LINE, nothing else — no preamble, no summary.

FORMAT, exactly:
[CLAIMED|L<line>] <what is wrong, one sentence>
[TASTE|L<line>|#<IC rule number>] <what would be cleaner, one sentence>

CLAIMED = a real defect: state mutated in two places, an index that can run off the end, a cap checked
after the push instead of before, a shuffle reseeded per call, anything order-dependent. Only report
what you can point at with a line number. If you are not sure, don't report it.

TASTE = style, and ONLY against the house rules below, named by number. Never freestyle about style.
If a finding does not match a numbered rule, it is not a TASTE finding. Leave it out.

THE HOUSE RULES (IC) — cite by number:
${icCard()}

Rules ${IC_RULES.filter(r => r.re || r.test).map(r => '#' + r.n).join(' ')} are already checked by machine.
Do not report those — they are handled. Spend your attention on the ones a machine cannot see.

Do NOT propose a new feature, ever. That is not this job — the crowd gets that vote, not you.
If you find nothing in a category, write no lines for it. Fewer, certain findings beat many guesses.
Finding nothing is a real answer, and a good one.

\`\`\`
${src}
\`\`\``
  }

  function sweepParse(text, fn) {
    const out = []
    String(text || '').split('\n').forEach(raw => {
      const m = /^\s*\[(CLAIMED|TASTE)(?:\|L(\d+))?(?:\|#?(\d+))?\]\s*(.+)$/.exec(raw)
      if (m) out.push({ kind: m[1], line: m[2] ? parseInt(m[2], 10) : 0, rule: m[3] || '', why: m[4].trim(), file: fn })
    })
    return out
  }

  // ── the list on disk. rewritten every time it grows, so a dead session loses nothing ─────────
  async function sweepSave() {
    if (!_sweep) return
    const by = {}
    _sweep.items.forEach(x => { (by[x.file] = by[x.file] || []).push(x) })
    const md = `# check work — ${_sweep.scope}\n\n${new Date().toISOString()} · ${_sweep.files} file(s) · ${_sweep.items.length} finding(s)\n` +
      (_sweep.items.length
        ? Object.keys(by).map(f => `\n## ${f}\n\n` + by[f].map(x => `- **${x.kind}**${x.line ? ` L${x.line}` : ''}${x.rule ? ` (IC #${x.rule})` : ''}${x.hits && x.hits.length > 1 ? ` ×${x.hits.length}` : ''} — ${x.why}`).join('\n')).join('\n')
        : '\n_nothing found._\n')
    try { const c = window.__TAURI__ && (window.__TAURI__.core || window.__TAURI__); if (c && c.invoke) await c.invoke('sandbox_write', { name: _sweep.path, content: md }) } catch (_) {}
  }

  // ── the sweep ────────────────────────────────────────────────────────────────────────────────
  async function sqSweep() {
    const targets = sweepTargets()
    if (!targets.length || !targets.some(t => t.src.trim())) { sqChatLog('assistant', 'nothing to check.'); return }
    if (_squiggy !== 'god') setSquiggyLevel('god')
    if (!_sqChatOn) toggleSqChat()

    const label = _sqScope === 'sandbox' ? 'the whole app' : _sqScope === 'tabs' ? 'all open tabs' : targets[0].name
    _sweep = { items: [], at: -1, scope: label, files: targets.length, path: 'sweeps/sweep-' + (_sqScope === 'tab' ? targets[0].name.replace(/[^\w.-]/g, '_') : _sqScope) + '.md' }

    // RUNG 1 over EVERY file first — free, so the list exists before a single token is spent.
    targets.forEach(t => { if (t.src.trim()) _sweep.items.push.apply(_sweep.items, sweepVerified(t.src, t.name)) })
    const nVerified = _sweep.items.length
    await sweepSave()
    sqChatLog('assistant', `🔍 ${label} — ${targets.length} file(s), ${targets.reduce((a, t) => a + t.src.split('\n').length, 0)} lines.\n${nVerified} verified issue(s) before a single token is spent. saved to ${_sweep.path}.`)

    if (!window.engineRaw) { sqChatLog('assistant', '(no engine — pick a model for Squiggy in ⚙ bots. the free pass above still stands.)'); if (_sweep.items.length) sweepNext(); return }

    // THE MODEL PASS — file by file, appending as each returns. press 🔍 to stop; the list keeps what it has.
    _sweepRun = true
    try { renderSqBox() } catch (_) {}
    const bubble = sqChatLog('assistant', 'asking…')
    for (let i = 0; i < targets.length && _sweepRun; i++) {
      const t = targets[i]
      if (!t.src.trim()) continue
      if (bubble) bubble.textContent = `reading ${i + 1}/${targets.length} — ${t.name}…`
      let acc = ''
      try {
        const res = await window.engineRaw({ agentId: MC_SQUIGGY, messages: [{ role: 'user', content: sweepPrompt(t.src, t.name) }], onChunk: c => { acc += c } })
        acc = (res && res.text) || acc
      } catch (e) { _sweep.items.push({ kind: 'CLAIMED', line: 0, file: t.name, why: 'could not read this one — ' + String((e && e.message) || e) }); continue }
      sweepParse(acc, t.name).forEach(x => _sweep.items.push(x))
      await sweepSave()
    }
    const stopped = !_sweepRun
    _sweepRun = false
    try { renderSqBox() } catch (_) {}

    // THE PAWL. A sweep that finished (not stopped) with nothing found is the ONLY thing that
    // unlocks rung 5. Stopping early does not count — you did not actually look at everything.
    _sweepClean = (!_sweep.items.length && !stopped) ? { scope: label, files: targets.length, at: Date.now() } : null

    const n = _sweep.items.length
    if (bubble) bubble.textContent = n
      ? `${n} finding(s)${stopped ? ' (stopped early)' : ''} — saved to ${_sweep.path}. walking them one at a time; press 🔍 for the next.`
      : `clean across ${targets.length} file(s). nothing to fix, nothing to tidy.` + (window.SQUIGGY_BETTER ? ' rungs 1–3 are empty — 🌍 make better just unlocked.' : '')
    try { renderSqBox() } catch (_) {}
    if (n) sweepNext()
  }

  function sweepStop() { _sweepRun = false; sqChatLog('assistant', 'stopping after this file — the list keeps everything found so far.') }

  // ── the walk. one finding, its fix in the box, the convo free to redirect it ──────────────────
  async function sweepNext() {
    if (!_sweep || !_sweep.items.length) { sqChatLog('assistant', 'no sweep running — press 🔍 check work.'); return }
    _sweep.at++
    if (_sweep.at >= _sweep.items.length) { sqChatLog('assistant', `that's all ${_sweep.items.length}. the full list stays at ${_sweep.path}.`); _sweep = null; return }
    const it = _sweep.items[_sweep.at], n = _sweep.at + 1, tot = _sweep.items.length
    const many = it.hits && it.hits.length > 1
    sqChatLog('assistant', `${SWEEP_RUNGS[it.kind] || '·'} ${n}/${tot} ${it.kind}${it.line ? ` L${it.line}` : ''}${it.rule ? ` (IC #${it.rule})` : ''}${many ? ` — ${it.hits.length} places` : ''}\n${it.file} · ${it.why}`)

    // walk into the file it is in — cross-file sweeps jump you there instead of describing somewhere else
    const cur = active()
    if (it.file && (!cur || cur.filename !== it.file)) { try { mcCliOpen(it.file) } catch (_) {} }
    if (it.line && editor) { try { editor.revealLineInCenter(it.line); editor.setPosition({ lineNumber: it.line, column: 1 }) } catch (_) {} }

    if (it.kind === 'CROWD') return                        // a note from the crowd, not a patch
    if (many) return sweepFixAll(it)                        // 200 of the same mistake is ONE press, not 200 steps
    // draft the fix NOW, against the file as it stands at this moment (it may have changed while you walked)
    await sqChatSend(`For finding ${n}/${tot} — ${it.kind}${it.line ? ` at L${it.line}` : ''}: ${it.why}\nGive me just the corrected snippet for that spot. No explanation unless something blocks you.`)
  }

  // ── FIX ALL — one call for every hit, one press to apply, ⌘Z to undo ──────────────────────────
  //    Sum: "fix all if 200 of same mistake." Walking 200 identical findings is not review, it is
  //    punishment. So the finding stays ONE finding and the fix arrives as a line map.
  async function sweepFixAll(it) {
    const t = active()
    if (!t || t.filename !== it.file || !editor) { sqChatLog('assistant', `open ${it.file} and press 🔍 again to fix all ${it.hits.length}.`); return }
    const model = editor.getModel(), src = editor.getValue().split('\n')
    const listing = it.hits.map(l => `L${l}| ${src[l - 1]}`).join('\n')
    const bubble = sqChatLog('assistant', `drafting ${it.hits.length} fixes…`)
    let acc = ''
    try {
      const res = await window.engineRaw({
        agentId: MC_SQUIGGY, onChunk: c => { acc += c },
        messages: [{ role: 'user', content: `In \`${it.file}\` these ${it.hits.length} lines all break the same rule:\n\n${it.why}\n\n${listing}\n\nRewrite EVERY line so it obeys the rule. Keep each line's exact indentation and everything else on it unchanged.\n\nFORMAT, one per line, nothing else — no fences, no prose:\nL<number>| <the corrected line>\n\nA line you cannot fix mechanically: leave it out entirely. Do not guess.` }]
      })
      acc = (res && res.text) || acc
    } catch (e) { if (bubble) bubble.textContent = '⚠ ' + String((e && e.message) || e); return }

    const edits = []
    acc.split('\n').forEach(raw => {
      const m = /^\s*L(\d+)\|\s?(.*)$/.exec(raw)
      if (!m) return
      const ln = parseInt(m[1], 10)
      if (it.hits.indexOf(ln) < 0 || ln < 1 || ln > src.length) return   // only lines WE flagged. no drive-by edits.
      edits.push({ range: new monaco.Range(ln, 1, ln, model.getLineMaxColumn(ln)), text: m[2] })
    })
    if (!edits.length) { if (bubble) bubble.textContent = `no mechanical fix offered for those ${it.hits.length} — walk them by hand or talk it through below.`; return }

    if (bubble) bubble.textContent = `${edits.length} of ${it.hits.length} lines have a fix. it stays in your hands — press to apply, ⌘Z undoes it.`
    const btn = node(`<button class="mc-sq-lintck" aria-label="apply ${edits.length} fixes to ${it.file}">apply ${edits.length} fixes</button>`)
    btn.addEventListener('click', () => {
      editor.executeEdits('sweep-fix-all', edits)
      btn.remove()
      sqChatLog('assistant', `applied ${edits.length} to ${it.file}. ⌘Z if it went wrong. press 🔍 for the next finding.`)
    })
    if (bubble) bubble.appendChild(btn)
  }

  // rung 5 hands its crowd findings back to THIS walk — one machine, five rungs, one ＋ to insert.
  function sweepAdopt(items, path) {
    _sweep = { items: items.slice(), at: -1, scope: 'the crowd', files: 1, path: path || 'sweeps/crowd.md' }
    if (_sweep.items.length) sweepNext()
  }

  window.SQUIGGY_SWEEP = {
    run: sqSweep, next: sweepNext, stop: sweepStop, adopt: sweepAdopt,
    running: () => _sweepRun, state: () => _sweep, clean: () => _sweepClean
  }
